/**
 * `outlook_ask_copilot` — put a question to Microsoft 365 Copilot with the
 * signed-in mailbox as its context.
 *
 * The answer is generated by Copilot's server-side `WorkSearch` over the user's
 * own mail, so it is third-party content twice over (the mail it draws on, and a
 * model's rendering of it): it goes back in the untrusted-data envelope, like
 * every other mail-derived read here. The turn reaches Microsoft's own Copilot
 * on the user's own tenant and changes nothing in the mailbox, so it is not
 * gated — but the prompt IS sent to that service, which is why the description
 * says so and why a prompt should carry the user's question, not text lifted
 * from an email.
 */
import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/server';
import { minifiedResult } from '@chrischall/mcp-utils';
import type { CopilotClient } from '../copilot/client.js';
import { DisengagedError } from '../copilot/session.js';
import { workMeta } from './_hints.js';
import { mailboxUntrusted, UNTRUSTED_DESCRIPTION_SUFFIX } from './_untrusted.js';

/** Stop a turn that outlives this, so a wedged connection cannot hang the call. */
const TURN_TIMEOUT_MS = 120_000;

/**
 * Abort when EITHER the host cancels the call or the turn runs past the timeout.
 * Returns the signal plus a disposer that clears the timer.
 */
function turnSignal(hostSignal: AbortSignal | undefined): { signal: AbortSignal; dispose: () => void } {
  const controller = new AbortController();
  const onAbort = () => controller.abort();
  if (hostSignal) {
    if (hostSignal.aborted) controller.abort();
    else hostSignal.addEventListener('abort', onAbort, { once: true });
  }
  const timer = setTimeout(() => controller.abort(), TURN_TIMEOUT_MS);
  timer.unref?.();
  return {
    signal: controller.signal,
    dispose: () => {
      clearTimeout(timer);
      hostSignal?.removeEventListener('abort', onAbort);
    },
  };
}

export function registerCopilotTools(server: McpServer, copilot: CopilotClient): void {
  server.registerTool(
    'outlook_ask_copilot',
    {
      description:
        'Ask Microsoft 365 Copilot a question answered from the signed-in mailbox (Copilot searches your own mail, calendar and files server-side and writes a reply). Use it for synthesis across many messages — "what needs my attention first", "summarise the thread with X", "did anyone ask me for anything this week". Follow-up calls continue the same conversation; pass newConversation:true to start fresh. The prompt is sent to Microsoft\'s Copilot service on your tenant; put your own question in it, not text copied from an email. Each call uses one of a per-conversation quota, reported back. First use needs a one-time sign-in: run `opencode-m365 login` (from the opencode-m365-copilot package) so an MSAL cache exists.' +
        UNTRUSTED_DESCRIPTION_SUFFIX,
      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: true },
      _meta: workMeta('lookup', { aliases: ['copilot', 'ask copilot', 'm365 copilot'] }),
      inputSchema: z.object({
        prompt: z.string().min(1).describe('The question for Copilot, in your own words'),
        newConversation: z
          .boolean()
          .optional()
          .describe('Start a fresh conversation with no prior context (default false: continue the current one)'),
      }),
    },
    async ({ prompt, newConversation }, ctx) => {
      if (newConversation) copilot.reset();
      const { signal, dispose } = turnSignal((ctx as { signal?: AbortSignal } | undefined)?.signal);
      try {
        const result = await copilot.ask(prompt, { signal });
        return mailboxUntrusted({
          answer: result.text,
          conversationId: copilot.conversationId,
          ...(result.throttle
            ? { quota: { used: result.throttle.current, max: result.throttle.max } }
            : {}),
          ...(result.contentOrigin ? { contentOrigin: result.contentOrigin } : {}),
        });
      } catch (e) {
        if (e instanceof DisengagedError) {
          // Not an error: Copilot's content filter returned an empty reply. Say
          // so plainly so the model can tell the user, and does not retry into it.
          return minifiedResult({
            disengaged: true,
            note:
              'Copilot declined to answer this prompt (its content filter returned nothing). ' +
              'Rephrasing more plainly, or asking a narrower question, usually helps. This is not a rate limit — do not retry the same prompt.',
          });
        }
        throw e;
      } finally {
        dispose();
      }
    },
  );
}
